const inchesToCm=inches=>inches*2.54;
function profileInputs(){let ft=$('profile_feet').value.trim(),inch=$('profile_inches').value.trim(),lb=$('profile_weight').value.trim();let feet=Number(ft),inches=Number(inch),pounds=Number(lb);return {height:ft!==''&&inch!==''&&feet>=3&&feet<=8&&Number.isInteger(feet)&&inches>=0&&inches<12?inchesToCm(feet*12+inches):NaN,weight:lb!==''&&pounds>=55&&pounds<=882?poundsToKg(pounds):NaN};}
function settingsPage(){let p=state.profile; $('goalInput').value=state.goal;$('mode').value=state.mode;let cm=Number(p.height),kg=Number(p.weight);if(p.height!==undefined&&p.height!==''&&cm>0){let totalIn=cm/2.54,ft=Math.floor(totalIn/12),inch=Math.round((totalIn-ft*12)*100)/100;if(inch>=12){ft++;inch=0}$('profile_feet').value=ft;$('profile_inches').value=inch}else{$('profile_feet').value='';$('profile_inches').value=''}$('profile_weight').value=p.weight!==undefined&&p.weight!==''&&kg>0?Math.round(kg*2.2046226218*10)/10:'';for(let id of ['age','sex','activity','deficit']){let el=$('profile_'+id);if(el)el.value=p[id]??(id==='activity'?'sedentary':id==='deficit'?'300':'')}showEstimate();}
function showEstimate(){let {height,weight}=profileInputs(),age=Number($('profile_age').value),sex=$('profile_sex').value,activity=$('profile_activity').value,deficit=Number($('profile_deficit').value);let info=$('calorieEstimate');if(!(height>=100&&height<=250&&weight>=25&&weight<=400&&age>=18&&age<=100&&['male','female'].includes(sex))){info.textContent='Enter your height (feet and inches), weight (lb), age (18+), and formula sex to calculate an estimate.';return null;}let maint=Math.round((10*weight+6.25*height-5*age+(sex==='male'?5:-161))*(activityFactors[activity]||1.2)),target=Math.round(maint-deficit);info.textContent=`Estimated maintenance: ${fmt(maint)} kcal/day. Weight-loss estimate: ${fmt(target)} kcal/day (${deficit} kcal deficit). Your saved goal will not change unless you choose Apply estimate.`;return {target};}
function saveSettings(){let n=Number($('goalInput').value);if(n<500||n>10000){notice('Enter a goal between 500 and 10,000 calories');return}state.goal=n;state.mode=$('mode').value;let p={...state.profile};let measurements=profileInputs();let entered=['profile_feet','profile_inches','profile_weight'].some(id=>$(id).value.trim()!=='');if(entered&&(!Number.isFinite(measurements.height)||!Number.isFinite(measurements.weight))){notice('Enter valid height in feet and inches and weight in pounds.');return}p.height=entered?String(measurements.height):'';p.weight=entered?String(measurements.weight):'';for(let id of ['age','sex','activity','deficit'])p[id]=$('profile_'+id).value;state.profile=p;persist();dashboard();notice('Settings saved')}
function estimateExerciseCal(met,minutes,kg){return Math.max(0,Math.round(met*3.5*kg/200*minutes));}
const exerciseTypes={cycling:['Cycling, moderate',6.8],strength:['Strength training',3.5],swimming:['Swimming, moderate',6],yoga:['Yoga',2.5],running:['Running, easy',8.3],other:['Other exercise',4]};
function stepBurn(count){let kg=Number(state.profile.weight);if(!(kg>0))return null;return Math.round(count*0.0005*kg);}
function activityFor(d){let ex=state.exercise.filter(x=>x.date===d),steps=Math.max(0,Number(state.steps[d])||0),stepCals=stepBurn(steps);return {ex,steps,stepCals,exerciseCals:ex.reduce((n,x)=>n+(Number(x.calories)||0),0)};}
function updateActivitySummary(){let a=activityFor(day),eaten=sum(byDate(day)).cal; $('activityToday').textContent=`${a.steps.toLocaleString()} steps · ${a.stepCals===null?'Add weight to estimate':a.stepCals+' kcal estimated walking'} · ${a.exerciseCals} kcal other exercise`;let burned=a.exerciseCals+(a.stepCals||0);$('netCalories').textContent=fmt(eaten-burned);$('activityBurned').textContent=fmt(burned);}
function exercisePage(){let a=activityFor(day);$('exerciseDate').textContent=day;$('stepsInput').value=a.steps||'';$('stepEstimate').textContent=a.stepCals===null?'Enter your weight in Settings for an estimate.':`Estimated ${a.stepCals} kcal from steps (rough estimate).`;let container=$('exerciseLog');container.replaceChildren();if(!a.ex.length)container.append(element('p','No exercises logged for this date.','hint'));a.ex.forEach(x=>{let row=element('div',undefined,'entry row'),left=element('div');left.append(element('b',x.name),element('div',`${x.minutes} min · ${x.calories} kcal${x.manual?' (manual)':' (estimated)'}`,'muted'));let b=element('button','Remove','mini');b.onclick=()=>{state.exercise=state.exercise.filter(y=>y.id!==x.id);persist();exercisePage();updateActivitySummary()};row.append(left,b);container.append(row)});$('exerciseTotals').textContent=`${a.steps.toLocaleString()} steps · ${a.stepCals??'—'} walking kcal · ${a.exerciseCals} exercise kcal`;}
$('saveSteps').onclick=()=>{let n=Number($('stepsInput').value);if(!Number.isInteger(n)||n<0||n>100000){notice('Enter a valid daily step count.');return}state.steps[day]=n;persist();exercisePage();updateActivitySummary();notice('Steps saved')};
$('exerciseType').onchange=()=>{$('exerciseCustomName').classList.toggle('hidden',$('exerciseType').value!=='other')};
$('addExercise').onclick=()=>{let type=$('exerciseType').value,minutes=Number($('exerciseMinutes').value),manual=$('exerciseManual').value.trim(),weight=Number(state.profile.weight);if(!(minutes>0&&minutes<=1440)){notice('Enter valid exercise minutes');return}if(type==='walking'){notice('Walking is tracked using your daily steps to avoid double-counting.');return}let kcal;if(manual!==''){kcal=Number(manual);if(!Number.isFinite(kcal)||kcal<0||kcal>10000){notice('Enter valid burned calories');return}}else{if(!(weight>0)){notice('Enter your weight in Settings first, or provide calories manually.');return}kcal=estimateExerciseCal(exerciseTypes[type][1],minutes,weight)}let name=type==='other'?$('exerciseCustomName').value.trim()||'Other exercise':exerciseTypes[type][0];state.exercise.push({id:'e'+Date.now()+Math.random(),date:day,name,minutes,calories:Math.round(kcal),manual:manual!==''});persist();$('exerciseMinutes').value='';$('exerciseManual').value='';exercisePage();updateActivitySummary();notice('Exercise saved')};
for(let id of ['feet','inches','weight','age','sex','activity','deficit'])$('profile_'+id).addEventListener('input',showEstimate);
$('applyEstimate').onclick=()=>{let e=showEstimate();if(!e)return;if(e.target<1200){notice('Estimate is low. Consult your healthcare professional before setting a low target.');return}$('goalInput').value=e.target;notice('Estimate entered as your goal. Tap Save settings to keep it.')};

